        return len(stack) == 0

    def remove_spaces(s: str) -> str:
        return ''.join(char for char in s if char != ' ')

    groups = []
    current_group = ''
    for char in paren_string:
        if char == '(':
            current_group += char
        elif char == ')':
            current_group += char
            if is_balanced(current_group):
                groups.append(remove_spaces(current_group))
                current_group = ''

    return groups

